    "adm.cost.howTitle": "Cómo se calcula",
    "adm.cost.howBody": "Para cada pedido pagado: del total se descuentan primero envío, impuestos y la comisión de Stripe (ingreso neto). Sobre el neto se aplican las partidas por porcentaje y la comisión del vendedor; los materiales (montura según ficha del modelo o de la marca, lentes, laboratorio, embalaje) se restan en importe fijo. Ganancia = total − todo lo anterior, y se compara con el objetivo (30 % del neto). También se calcula el precio al que la venta habría cubierto costos y objetivo. Puedes ajustar la ficha de un pedido a mano; costo y margen se escriben en la hoja de Google.",
