    "coat.ar": "Antirreflejo", "coat.blue": "Filtro luz azul", "coat.photo": "Fotocromático", "coat.tint": "Tinte de sol",
    "coat.ar.tip": "Elimina reflejos molestos y mejora la nitidez, sobre todo al conducir de noche o frente a pantallas. Recomendado para casi todos.",
    "coat.blue.tip": "Reduce la luz azul de pantallas; conviene si pasas muchas horas en computadora o teléfono. No necesario si casi no usas pantallas.",
    "coat.photo.tip": "El lente se oscurece con el sol y se aclara en interiores. Ideal si quieres un solo par para dentro y fuera; no reemplaza gafas de sol al conducir.",
    "coat.tint.tip": "Tinte permanente estilo gafas de sol. Recomendado para exteriores; no apto como lente de uso interior.",
    "footer.about": "RUBI LENS — espejuelos de marca online. Bienestar y estilo para tu visión.",
