    "footer.admin": "Panel corporativo",
    // Ventanas emergentes del pie (fi.*): cada enlace explicado en detalle.
    "fi.close": "Cerrar",
    "env.banner.staging": "STAGING · Entorno de pruebas: lo que se haga aquí no llega a la tienda real. No hagas compras reales.",
    "env.banner.custom": "ENTORNO DE PRUEBAS · Esta versión no usa el servidor de producción.",
    "resume.title": "Retoma donde lo dejaste", "resume.cta": "Continuar",
    "fi.choose.title": "Cómo elegir tu montura",
    "fi.choose.intro": "Elegir bien es cuestión de tres cosas: la forma de tu rostro, las medidas correctas y el uso que le vas a dar. Aquí te lo explicamos paso a paso.",
    "fi.choose.s1t": "Según la forma de tu rostro",
    "fi.choose.s1b": "Rostro redondo: monturas angulares (cuadradas o rectangulares) que aportan definición. Rostro cuadrado: redondas u ovaladas que suavizan los rasgos. Rostro ovalado: casi cualquier estilo te favorece. Rostro en forma de corazón: cat-eye o aviador ligeros equilibran la frente.",
    "fi.choose.s2t": "Las medidas correctas",
    "fi.choose.s2b": "En la varilla de tus gafas actuales verás tres números, por ejemplo 49-19-138: calibre del lente, puente y largo de varilla, en milímetros. Compara con una montura que te quede bien. Cada producto muestra sus medidas, y nuestro medidor con IA calcula tu distancia interpupilar con la cámara.",
    "fi.choose.s3t": "Pruébatelos sin salir de casa",
    "fi.choose.s3b": "Usa el botón \"Pruébamelos\" para ver la montura sobre tu propia foto, y el sello 360° para girarla y verla desde todos los ángulos. En el catálogo puedes filtrar por forma, material, sexo, edad y estilo.",
    "fi.choose.s4t": "Material y uso diario",
    "fi.choose.s4b": "Metal y acero inoxidable: ligeros y duraderos, ideales para uso diario. Acetato: más color y presencia. TR90 y titanio flexible: resistentes a golpes, perfectos para niños y deporte. Si pasas horas frente a pantallas, añade el filtro de luz azul al configurar tus lentes.",
    "fi.rx.title": "Guía de recetas",
    "fi.rx.intro": "Tu receta tiene toda la información que el laboratorio necesita. Así se lee y así la usamos para fabricar tus lentes exactos.",
    "fi.rx.s1t": "Qué significa cada valor",
    "fi.rx.s1b": "OD es tu ojo derecho y OS (u OI) el izquierdo. SPH (esfera) corrige miopía (signo −) o hipermetropía (signo +). CYL (cilindro) y EJE corrigen el astigmatismo: siempre van juntos. ADD es la adición para lectura en lentes progresivos o bifocales.",
    "fi.rx.s2t": "La distancia interpupilar (DIP)",
    "fi.rx.s2b": "Es la distancia en milímetros entre tus pupilas y centra los lentes frente a tus ojos. Si tu receta no la incluye, nuestro medidor con IA la calcula con tu cámara en un minuto, con corrección de cerca a lejos para que el valor sea el correcto para ver de lejos.",
    "fi.rx.s3t": "Cómo cargarla al comprar",
    "fi.rx.s3b": "En el asistente de lentes, sube una foto nítida de tu receta: la IA la lee y te pre-llena los valores. Revísalos y confírmalos siempre antes de pagar — tú tienes la última palabra sobre cada número.",
    "fi.rx.s4t": "Vigencia y dudas",
    "fi.rx.s4b": "Usa una receta de menos de dos años. Si notas cambios de visión, dolores de cabeza o la receta es antigua, visita primero a tu optometrista. Esta guía es informativa y no sustituye el consejo de un profesional de la salud visual.",
    "fi.ship.title": "Envíos y devoluciones",
    "fi.ship.intro": "Enviamos con FedEx y te mantenemos informado en cada etapa del pedido, del laboratorio a tu puerta.",
    "fi.ship.s1t": "Cobertura y mensajería (FedEx)",
    "fi.ship.s1b": "Por ahora enviamos solo dentro de Estados Unidos, siempre con FedEx. Al poner tu dirección en el checkout verás el costo y el plazo de entrega de FedEx para tu pedido.",
    "fi.ship.s2t": "Tarifa clara, sin sorpresas",
    "fi.ship.s2b": "El costo del envío se muestra en el checkout antes de pagar, con el desglose de cada mensajería (FedEx llega en unos 4 días). Lo que ves ahí es exactamente lo que se cobra.",
    "fi.ship.s3t": "Tiempos y seguimiento",
    "fi.ship.s3b": "Los lentes con receta se fabrican en nuestro laboratorio en unos 10 días hábiles; después sale el envío. Sigue cada etapa — confirmado, en laboratorio, enviado, en camino, entregado — desde \"Mi cuenta\", y si lo activas te avisamos por correo y SMS en cada cambio.",
    "fi.ship.s4t": "Devoluciones y cancelaciones",
    "fi.ship.s4b": "Tienes garantía de 30 días desde la entrega. La cancelación se solicita desde tus pedidos y aplica según la política de la tienda (si el paquete ya salió, se gestiona como devolución al recibirlo). Cualquier caso se abre desde el mismo panel de tus pedidos.",
    "fi.gar.title": "Garantía de 30 días",
    "fi.gar.intro": "Queremos que estrenes con tranquilidad: todos los espejuelos tienen 30 días de garantía desde que te llegan.",
    "fi.gar.s1t": "Qué cubre",
    "fi.gar.s1b": "Defectos de fabricación de la montura o de los lentes, lentes que no corresponden con la receta confirmada y fallos de montaje del laboratorio. Si algo de esto pasa, lo resolvemos sin costo para ti.",
    "fi.gar.s2t": "Qué no cubre",
    "fi.gar.s2b": "Golpes, caídas, rayones por el uso, exposición a calor extremo o productos químicos, y la pérdida de la montura. Los ajustes normales de varillas y plaquetas los puede hacer cualquier óptica local.",
    "fi.gar.s3t": "Cómo reclamar",
    "fi.gar.s3b": "Entra a \"Mi cuenta\" con tu correo, abre el pedido y crea un caso de soporte contando qué pasó, con fotos si es posible. Te respondemos en 24–48 horas hábiles.",
    "fi.gar.s4t": "Cómo se resuelve",
    "fi.gar.s4b": "Según el caso: reparación, reemplazo o reembolso. El reemplazo por defecto de fabricación corre por nuestra cuenta. Tu dinero vuelve por el mismo medio de pago de la compra.",
    "fi.upload.title": "Sube tu receta",
    "fi.upload.intro": "Subir tu receta toma un minuto y nos asegura fabricar exactamente los lentes que tu optometrista indicó.",
    "fi.upload.s1t": "Cuándo se sube",
    "fi.upload.s1b": "Durante el asistente de lentes, en el paso de la receta: elige \"Subir receta\" y continúa con tu compra normalmente. También puedes escribir los valores a mano si los conoces.",
    "fi.upload.s2t": "Cómo tomar la foto",
    "fi.upload.s2b": "Foto nítida, con buena luz y las cuatro esquinas del papel visibles, en JPG o PNG. Evita sombras y reflejos sobre los números: una buena foto hace la lectura automática mucho más precisa.",
    "fi.upload.s3t": "Lectura automática con IA",
    "fi.upload.s3b": "Nuestro sistema lee la receta y te pre-llena SPH, CYL, EJE, ADD y DIP. Tú revisas cada valor y lo confirmas antes de pagar; nada se fabrica sin tu confirmación.",
    "fi.upload.s4t": "Tu privacidad",
    "fi.upload.s4b": "La receta es un dato de salud: se guarda en almacenamiento privado, con enlaces temporales de acceso, y solo la ve el equipo del laboratorio para fabricar tus lentes. Nunca se comparte con terceros.",
    "fi.contact.title": "Contacto",
    "fi.contact.intro": "Estamos para ayudarte antes, durante y después de tu compra. Estas son las vías más rápidas.",
    "fi.contact.s1t": "Soporte de tu pedido",
    "fi.contact.s1b": "Entra a \"Mi cuenta\" con tu correo (te llega un enlace seguro, sin contraseñas), abre tu pedido y crea un hilo de soporte. Todo queda escrito y vinculado a tu compra.",
    "fi.contact.s2t": "Tiempo de respuesta",
    "fi.contact.s2b": "Respondemos en 24–48 horas hábiles. Los casos de garantía y los pedidos en camino tienen prioridad.",
    "fi.contact.s3t": "Asesoría óptica",
    "fi.contact.s3b": "¿Dudas de tallas, formas, materiales o recetas antes de comprar? Usa el chat de la esquina inferior derecha y te orientamos con gusto.",
    "fi.contact.s4t": "Empresas y mayoristas",
    "fi.contact.s4b": "Si buscas volumen para tu óptica o tu empresa, abre un caso indicando \"mayorista\" y el equipo comercial te contacta con condiciones especiales.",

