    "coat.ar": "Anti-reflective", "coat.blue": "Blue-light filter", "coat.photo": "Photochromic", "coat.tint": "Sun tint",
    "coat.ar.tip": "Removes distracting glare and improves clarity, especially when driving at night or facing screens. Recommended for almost everyone.",
    "coat.blue.tip": "Reduces screen blue light; useful if you spend many hours on computer or phone. Not needed if you rarely use screens.",
    "coat.photo.tip": "The lens darkens in sunlight and clears indoors. Great for a single pair for in and out; doesn't replace sunglasses when driving.",
    "coat.tint.tip": "Permanent sunglass-style tint. Recommended for outdoors; not suitable as an indoor lens.",
