    "fi.close": "Close",
    "env.banner.staging": "STAGING · Test environment: nothing done here reaches the real store. Do not make real purchases.",
    "env.banner.custom": "TEST ENVIRONMENT · This build does not use the production server.",
    "resume.title": "Pick up where you left off", "resume.cta": "Continue",
    "fi.choose.title": "How to choose your frame",
    "fi.choose.intro": "Choosing well comes down to three things: your face shape, the right measurements and how you will use them. Here it is, step by step.",
    "fi.choose.s1t": "By face shape",
    "fi.choose.s1b": "Round face: angular frames (square or rectangular) add definition. Square face: round or oval shapes soften features. Oval face: almost any style works. Heart-shaped face: light cat-eye or aviator frames balance the forehead.",
    "fi.choose.s2t": "The right measurements",
    "fi.choose.s2b": "On the temple arm of your current glasses you will find three numbers, e.g. 49-19-138: lens width, bridge and temple length, in millimeters. Compare with a frame that fits you well. Every product lists its measurements, and our AI tool measures your pupillary distance with your camera.",
    "fi.choose.s3t": "Try them on from home",
    "fi.choose.s3b": "Use the \"Try them on\" button to see the frame on your own photo, and the 360° badge to spin it and see every angle. In the catalog you can filter by shape, material, gender, age and style.",
    "fi.choose.s4t": "Material and daily use",
    "fi.choose.s4b": "Metal and stainless steel: light and durable, great for everyday wear. Acetate: more color and presence. TR90 and flexible titanium: impact-resistant, perfect for kids and sports. If you spend hours on screens, add the blue-light filter when configuring your lenses.",
    "fi.rx.title": "Prescription guide",
    "fi.rx.intro": "Your prescription holds everything the lab needs. Here is how to read it and how we use it to craft your exact lenses.",
    "fi.rx.s1t": "What each value means",
    "fi.rx.s1b": "OD is your right eye and OS your left. SPH (sphere) corrects nearsightedness (− sign) or farsightedness (+ sign). CYL (cylinder) and AXIS correct astigmatism and always go together. ADD is the reading addition for progressive or bifocal lenses.",
    "fi.rx.s2t": "Pupillary distance (PD)",
    "fi.rx.s2b": "It is the distance in millimeters between your pupils and it centers the lenses in front of your eyes. If your prescription does not include it, our AI tool measures it with your camera in a minute, with near-to-far correction so the value is right for distance vision.",
    "fi.rx.s3t": "How to add it when buying",
    "fi.rx.s3b": "In the lens wizard, upload a sharp photo of your prescription: the AI reads it and pre-fills the values. Always review and confirm them before paying — you have the final say on every number.",
    "fi.rx.s4t": "Validity and doubts",
    "fi.rx.s4b": "Use a prescription under two years old. If you notice vision changes, headaches, or your prescription is old, see your optometrist first. This guide is informational and does not replace professional eye-care advice.",
    "fi.ship.title": "Shipping & returns",
    "fi.ship.intro": "We ship with FedEx and keep you posted at every stage, from the lab to your door.",
    "fi.ship.s1t": "Coverage and carrier (FedEx)",
    "fi.ship.s1b": "For now we ship within the United States only, always with FedEx. Enter your address at checkout and you will see the FedEx cost and delivery time for your order.",
    "fi.ship.s2t": "Clear rates, no surprises",
    "fi.ship.s2b": "Shipping cost shows at checkout before you pay, itemized per carrier (FedEx arrives in about 4 days). What you see there is exactly what you are charged.",
    "fi.ship.s3t": "Times and tracking",
    "fi.ship.s3b": "Prescription lenses are crafted in our lab in about 10 business days; then the package ships. Follow every stage — confirmed, in lab, shipped, in transit, delivered — from \"My account\", and if you opt in we notify you by email and SMS on every change.",
    "fi.ship.s4t": "Returns and cancellations",
    "fi.ship.s4b": "You have a 30-day guarantee from delivery. Cancellation is requested from your orders and applies per store policy (if the package already left, it is handled as a return on arrival). Any case is opened from the same orders panel.",
    "fi.gar.title": "30-day guarantee",
    "fi.gar.intro": "We want you to enjoy your new glasses with peace of mind: every pair carries a 30-day guarantee from the day it arrives.",
    "fi.gar.s1t": "What it covers",
    "fi.gar.s1b": "Manufacturing defects in the frame or lenses, lenses that do not match the confirmed prescription, and lab assembly faults. If any of this happens, we fix it at no cost to you.",
    "fi.gar.s2t": "What it does not cover",
    "fi.gar.s2b": "Impacts, drops, scratches from use, exposure to extreme heat or chemicals, and losing the frame. Routine temple and nose-pad adjustments can be done at any local optician.",
    "fi.gar.s3t": "How to claim",
    "fi.gar.s3b": "Sign in to \"My account\" with your email, open the order and create a support case telling us what happened, with photos if possible. We reply within 24–48 business hours.",
    "fi.gar.s4t": "How it is resolved",
    "fi.gar.s4b": "Depending on the case: repair, replacement or refund. Replacements for manufacturing defects are on us. Refunds go back to the same payment method you used.",
    "fi.upload.title": "Upload your prescription",
    "fi.upload.intro": "Uploading your prescription takes a minute and ensures we craft exactly the lenses your optometrist prescribed.",
    "fi.upload.s1t": "When to upload it",
    "fi.upload.s1b": "During the lens wizard, at the prescription step: choose \"Upload prescription\" and continue your purchase normally. You can also type the values by hand if you know them.",
    "fi.upload.s2t": "How to take the photo",
    "fi.upload.s2b": "A sharp photo, in good light, with all four corners of the paper visible, in JPG or PNG. Avoid shadows and glare over the numbers: a good photo makes the automatic reading far more accurate.",
    "fi.upload.s3t": "AI automatic reading",
    "fi.upload.s3b": "Our system reads the prescription and pre-fills SPH, CYL, AXIS, ADD and PD. You review each value and confirm it before paying; nothing is crafted without your confirmation.",
    "fi.upload.s4t": "Your privacy",
    "fi.upload.s4b": "A prescription is health data: it is stored privately, behind temporary access links, and only the lab team sees it to craft your lenses. It is never shared with third parties.",
    "fi.contact.title": "Contact",
    "fi.contact.intro": "We are here to help before, during and after your purchase. These are the fastest ways to reach us.",
    "fi.contact.s1t": "Order support",
    "fi.contact.s1b": "Sign in to \"My account\" with your email (you get a secure link, no passwords), open your order and create a support thread. Everything stays in writing, linked to your purchase.",
    "fi.contact.s2t": "Response time",
    "fi.contact.s2b": "We reply within 24–48 business hours. Guarantee cases and orders in transit get priority.",
    "fi.contact.s3t": "Optical advice",
    "fi.contact.s3b": "Questions about sizes, shapes, materials or prescriptions before buying? Use the chat at the bottom-right corner and we will gladly guide you.",
    "fi.contact.s4t": "Business and wholesale",
    "fi.contact.s4b": "Looking for volume for your optical shop or company? Open a case mentioning \"wholesale\" and our sales team will reach out with special terms.",

